import { Client, Environment, OrdersController, CheckoutPaymentIntent } from '@paypal/paypal-server-sdk';

const client = new Client({
  clientCredentialsAuthCredentials: {
    oAuthClientId: process.env.PAYPAL_CLIENT_ID!,
    oAuthClientSecret: process.env.PAYPAL_CLIENT_SECRET!,
  },
  environment: Environment.Sandbox,
});

const ordersController = new OrdersController(client);

// Create an order and get the approval URL
const { body: order } = await ordersController.ordersCreate({
  body: {
    intent: CheckoutPaymentIntent.Capture,
    purchaseUnits: [
      {
        amount: {
          currencyCode: 'USD',
          value: '20.00',
        },
        description: 'Pro Plan Subscription',
        referenceId: 'order_123',
      },
    ],
    applicationContext: {
      returnUrl: 'https://yourapp.com/checkout/success',
      cancelUrl: 'https://yourapp.com/checkout/cancel',
      brandName: 'Your App',
      userAction: 'PAY_NOW',
    },
  },
  prefer: 'return=representation',
});

// Find the approval URL to redirect the customer
const approvalLink = order.links?.find((link) => link.rel === 'approve');
console.log('Redirect customer to:', approvalLink?.href);
console.log('Order ID:', order.id);

import { Client, Environment, OrdersController } from '@paypal/paypal-server-sdk';

const client = new Client({
  clientCredentialsAuthCredentials: {
    oAuthClientId: process.env.PAYPAL_CLIENT_ID!,
    oAuthClientSecret: process.env.PAYPAL_CLIENT_SECRET!,
  },
  environment: Environment.Sandbox,
});

const ordersController = new OrdersController(client);

// orderId comes from query param ?token= on your returnUrl
async function capturePayPalOrder(orderId: string): Promise<void> {
  const idempotencyKey = `capture-${orderId}-${Date.now()}`;

  const { body: captureResult, statusCode } = await ordersController.ordersCapture({
    id: orderId,
    prefer: 'return=representation',
    paypalRequestId: idempotencyKey, // Idempotency key for safe retries
  });

  if (statusCode !== 201) {
    console.error('Capture failed with status:', statusCode);
    throw new Error(`PayPal capture failed: ${statusCode}`);
  }

  const captureStatus = captureResult.status;
  const captureId = captureResult.purchaseUnits?.[0]?.payments?.captures?.[0]?.id;

  if (captureStatus === 'COMPLETED') {
    console.log('Payment captured successfully. Capture ID:', captureId);
    // Fulfill the order — provision access, send confirmation email, etc.
    await fulfillOrder(orderId, captureId!);
  } else {
    console.warn('Unexpected capture status:', captureStatus);
  }
}

async function fulfillOrder(orderId: string, captureId: string) {
  // Your order fulfillment logic here
}
